set -euo pipefail
cp -R "$1/py-calc/." .
cat > calc/fmt.py <<'EOF'
"""Formatting helpers for report output."""


def money(amount):
    """Format amount as dollars, with a leading minus for negatives."""
    if amount < 0:
        return f"-${-amount:.2f}"
    return f"${amount:.2f}"
EOF
cat > calc/types.py <<'EOF'
"""Shared value types."""

from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from decimal import Decimal


class Money:
    """An amount of money."""

    def __init__(self, amount: "Decimal"):
        self.amount = amount
EOF
cat > calc/_rates.py <<'EOF'
# Generated by tools/gen_rates.py from rates.csv. Do not edit by hand.
RATES = {
    "EUR": 0.92,
    "GBP": 0.79,
    "JPY": 151.3,
}
EOF
cat > tests/helpers.py <<'EOF'
"""Builders shared by the tests."""


def amounts(*values):
    return list(values)
EOF
